import { randomBytes } from "crypto";

/** A session ends after this much inactivity (matches the _pm_sid cookie). */
export const SESSION_TIMEOUT_MS = 30 * 60 * 1000;

export function generateVisitorId(): string {
  return randomBytes(16).toString("hex");
}

export function generateSessionId(): string {
  return randomBytes(16).toString("hex");
}

/**
 * Accept only id-shaped strings from client input (body/query). Ids are
 * UUIDs / hex generated by the script or server, optionally prefixed.
 */
export function sanitizeTrackingId(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  if (!trimmed || trimmed.length > 64) return null;
  if (!/^[A-Za-z0-9_-]+$/.test(trimmed)) return null;
  return trimmed;
}

export function getVisitorIdFromCookie(
  cookieHeader: string | null
): string | null {
  if (!cookieHeader) return null;

  const cookies = cookieHeader.split(";").reduce((acc, cookie) => {
    const [key, value] = cookie.trim().split("=");
    acc[key] = value;
    return acc;
  }, {} as Record<string, string>);

  return cookies["_pm_vid"] || null;
}

export function getSessionIdFromCookie(
  cookieHeader: string | null
): string | null {
  if (!cookieHeader) return null;

  const cookies = cookieHeader.split(";").reduce((acc, cookie) => {
    const [key, value] = cookie.trim().split("=");
    acc[key] = value;
    return acc;
  }, {} as Record<string, string>);

  return cookies["_pm_sid"] || null;
}

export function createVisitorIdCookie(
  visitorId: string,
  isSecure: boolean = false
): string {
  const secureFlag = isSecure ? "; Secure" : "";
  return `_pm_vid=${visitorId}; Path=/; Max-Age=31536000; SameSite=Lax${secureFlag}`;
}

export function createSessionIdCookie(
  sessionId: string,
  isSecure: boolean = false
): string {
  const secureFlag = isSecure ? "; Secure" : "";
  return `_pm_sid=${sessionId}; Path=/; Max-Age=1800; SameSite=Lax${secureFlag}`; // 30 minutes
}
